package com.fertiplus.payment;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="payments",uniqueConstraints=@UniqueConstraint(name="uk_payment_order",columnNames="order_reference")) public class PaymentRecord { @Id public String id; @Column(name="order_reference",nullable=false,unique=true) public String orderReference; @Column(nullable=false) public double amount; @Column(nullable=false) public String currency; @Column(nullable=false) public String status; @Column(nullable=false) public Instant createdAt=Instant.now(); protected PaymentRecord(){} public PaymentRecord(String id,String orderReference,double amount,String currency,String status){this.id=id;this.orderReference=orderReference;this.amount=amount;this.currency=currency;this.status=status;} }
